import csv, json, collections
from fractions import Fraction as F
def rd(p): return list(csv.DictReader(open(p)))
plan={r['run_id']:r for r in rd('plan.csv')}
launch=rd('launch_log.csv')
res={}
for r in rd('eval_results.csv'):
    assert r['run_id'] not in res; res[r['run_id']]=F(r['pass_rate'])
runtime={}
for r in rd('runtime.csv'):
    assert r['run_id'] not in runtime; runtime[r['run_id']]=r['finished_at']
ret={}
for r in rd('retention_log.csv'):
    assert r['run_id'] not in ret; ret[r['run_id']]=r
digest={r['date']:(int(r['n_runs']),F(r['sum_pass_rate'])) for r in rd('daily_digest.csv')}
suites=json.load(open('suites.json'))
policy=json.load(open('retention_policy.json'))
rec={}
import glob
for f in sorted(glob.glob('recovered/*.csv')):
    for r in rd(f):
        v=F(r['pass_rate_pct'])/100
        if r['run_id'] in rec: assert rec[r['run_id']]==v,(r,rec[r['run_id']])
        rec[r['run_id']]=v
reclog=rd('recovery_log.csv')
# launched set
L={}
for r in launch:
    if r['run_id'] in L:
        if L[r['run_id']]!=(r['started_at'],r['worker']): print('DUP DIFF',r,L[r['run_id']])
    L[r['run_id']]=(r['started_at'],r['worker'])
print('launched unique',len(L),'rows',len(launch))
print('plan',len(plan),'results',len(res),'runtime',len(runtime),'rec',len(rec))
print('launched not in plan',[k for k in L if k not in plan])
print('results not launched',[k for k in res if k not in L])
print('runtime not launched',[k for k in runtime if k not in L], 'launched w/o runtime',[k for k in L if k not in runtime])
print('rec not launched',[k for k in rec if k not in L])
print('ret not launched',[k for k in ret if k not in L])
print('res & ret',[k for k in res if k in ret])
def floor_at(t):
    for v in policy['versions']:
        if v['from']<=t<v['to']: return F(str(v['floor']))
    raise Exception(t)
def lower(run):
    s=suites[plan[run]['suite']]
    return F(str(s['random_guess'])) if s['scoring']=='raw' else F(0)
# classify
state={}; box={}
for run,(st,w) in L.items():
    fin=runtime[run]
    if run in res:
        state[run]='kept'; box[run]=(res[run],res[run])
    elif run in ret:
        if ret[run]['reason']=='below_retention_floor':
            state[run]='screened'; fl=floor_at(ret[run]['dropped_at'])
            box[run]=(lower(run),fl-F(1,10000))
            assert ret[run]['dropped_at']==fin,(run,ret[run],fin)
        else:
            state[run]='shardlost'; fl=floor_at(fin); box[run]=(fl,F(1))
            assert w=='w01' and fin[:10]=='2026-07-04',(run,w,fin)
    else:
        if w in('w03','w07') and '2026-06-27T00:00:00Z'<=st<'2026-07-03T12:00:00Z':
            state[run]='inc4471'
        elif w=='w09' and '2026-07-11T00:00:00Z'<=st<'2026-07-15T00:00:00Z':
            state[run]='inc4530'
        else:
            state[run]='UNKNOWN'; print('unknown',run,st,w,fin)
        box[run]=(lower(run),F(1))
    if run in rec:
        if run in res: assert rec[run]==res[run],(run)
        else:
            lo,hi=box[run]; assert lo<=rec[run]<=hi,(run,state[run],box[run],rec[run])
            box[run]=(rec[run],rec[run])
print(collections.Counter(state.values()))
print('rec by state',collections.Counter(state[r] for r in rec if r in L))
# check all runs on w03/w07 in window are missing
for run,(st,w) in L.items():
    if w in('w03','w07') and '2026-06-27T00:00:00Z'<=st<'2026-07-03T12:00:00Z' and (run in res or run in ret): print('inwindow but has row',run,state[run])
    if w=='w09' and '2026-07-11T00:00:00Z'<=st and (run in res or run in ret): print('w09 late has row',run)
# recovery log
for r in reclog:
    run=r['run_id']; print(run,state.get(run),plan[run]['suite'],plan[run]['curriculum'],r['outcome'],r['returned_lo'],r['returned_hi'],F(r['returned_hi'])-F(r['returned_lo']),box.get(run),L.get(run),runtime.get(run))
EOF
